package com.bank.chain.service;

import com.bank.chain.exception.TradeSettlementException;
import java.sql.SQLException;

public class SettlementService {

    // ═══ CHAINING: wrap low-level in domain exception ═══
    public void settleTrade(String tradeId) {
        try {
            executeDbUpdate(tradeId);  // might throw SQLException
        } catch (SQLException e) {
            // WRAP: domain exception + original cause
            throw new TradeSettlementException(tradeId, "DB update failed", e);
            // Caller sees: TradeSettlementException (domain)
            // Cause chain: TradeSettlementException → SQLException → (possible deeper cause)
        }
    }

    // Simulated DB call that throws:
    private void executeDbUpdate(String tradeId) throws SQLException {
        if ("TRD-FAIL".equals(tradeId)) {
            throw new SQLException("Connection refused: localhost:5432",
                new java.net.ConnectException("Connection refused"));
            // Multi-level: ConnectException → SQLException → TradeSettlementException
        }
    }

    // ═══ WITHOUT chaining: leaks implementation detail ═══
    public void settleTradeLeaky(String tradeId) throws SQLException {
        executeDbUpdate(tradeId);
        // SQLException LEAKS to caller → controller depends on java.sql!
    }
}
