// ─── File: src/test/java/com/bank/chain/ExceptionChainingTest.java ───
package com.bank.chain;

import com.bank.chain.exception.TradeSettlementException;
import com.bank.chain.service.SettlementService;
import org.junit.jupiter.api.Test;
import java.sql.SQLException;
import static org.assertj.core.api.Assertions.*;

class ExceptionChainingTest {

    SettlementService service = new SettlementService();

    @Test
    void chaining_domainExceptionWrapsLowLevel() {
        assertThatThrownBy(() -> service.settleTrade("TRD-FAIL"))
            .isInstanceOf(TradeSettlementException.class)
            .hasMessageContaining("Settlement failed for TRD-FAIL")
            .hasMessageContaining("DB update failed");
        // Caller sees domain exception with meaningful message!
    }

    @Test
    void chaining_getCauseRetrievesOriginal() {
        try {
            service.settleTrade("TRD-FAIL");
        } catch (TradeSettlementException e) {
            assertThat(e.getCause()).isInstanceOf(SQLException.class);
            assertThat(e.getCause().getMessage()).contains("Connection refused");
            // Original SQLException preserved via getCause()!
        }
    }

    @Test
    void chaining_multiLevelCause() {
        try {
            service.settleTrade("TRD-FAIL");
        } catch (TradeSettlementException e) {
            // Level 1: TradeSettlementException
            assertThat(e).isInstanceOf(TradeSettlementException.class);
            // Level 2: SQLException
            assertThat(e.getCause()).isInstanceOf(SQLException.class);
            // Level 3: ConnectException (root cause!)
            assertThat(e.getCause().getCause()).isInstanceOf(java.net.ConnectException.class);
            // Full chain preserved: Trade → SQL → Network
        }
    }

    @Test
    void chaining_tradeIdPreserved() {
        try {
            service.settleTrade("TRD-FAIL");
        } catch (TradeSettlementException e) {
            assertThat(e.getTradeId()).isEqualTo("TRD-FAIL");
            // Domain-specific context (tradeId) available on the exception!
        }
    }

    @Test
    void noChaining_leaksSqlException() {
        assertThatThrownBy(() -> service.settleTradeLeaky("TRD-FAIL"))
            .isInstanceOf(SQLException.class);
        // (Avoid) Controller now depends on java.sql!
        // (Avoid) Customer sees: "Connection refused: localhost:5432" — security risk!
    }

    @Test
    void stackTraceShowsCausedBy() {
        try {
            service.settleTrade("TRD-FAIL");
        } catch (TradeSettlementException e) {
            // e.printStackTrace() would show:
            // TradeSettlementException: Settlement failed for TRD-FAIL: DB update failed
            //   at SettlementService.settleTrade(...)
            // Caused by: java.sql.SQLException: Connection refused: localhost:5432
            //   at SettlementService.executeDbUpdate(...)
            // Caused by: java.net.ConnectException: Connection refused
            //   at ...
            assertThat(e.getMessage()).contains("TRD-FAIL");
            assertThat(e.getCause().getMessage()).contains("Connection refused");
        }
    }
}
